<?php
/** Bounded photo uploads and explicit proxy rejections in the disposable offline QA site. */
require __DIR__ . '/publication-formats.php';
add_filter( 'pre_http_request', 'threadtandem_test_http', 10, 3 );
$pixels = imagecreatetruecolor( 1800, 1000 );
for ( $x = 0; $x < 1800; $x++ ) { imageline( $pixels, $x, 0, $x, 999, imagecolorallocate( $pixels, $x % 256, ( $x * 3 ) % 256, ( $x * 7 ) % 256 ) ); }
ob_start(); imagepng( $pixels, null, 0 ); $original = ob_get_clean(); imagedestroy( $pixels );
$upload = wp_upload_bits( 'qa-large-poster.png', null, $original );
threadtandem_test_expect( ! $upload['error'] && strlen( $original ) > 1024 * 1024, 'Large valid PNG fixture exceeds a common reverse-proxy upload limit' );
$image_id = wp_insert_attachment( array( 'post_title' => 'Large poster QA', 'post_mime_type' => 'image/png', 'post_status' => 'inherit' ), $upload['file'] );
$id = wp_insert_post( array( 'post_title' => 'Bounded photo upload', 'post_status' => 'draft', 'meta_input' => array( '_thumbnail_id' => $image_id ) ) );
$temporary_before = glob( get_temp_dir() . 'threadtandem-photo-*' );
$media = ThreadTandem_Media::for_post( get_post( $id ) );
threadtandem_test_expect( ! is_wp_error( $media ) && strlen( $media['files']['photo']['data'] ) <= 900 * 1024 && $media['files']['photo']['type'] === 'image/jpeg', 'A large local PNG becomes a JPEG upload no larger than 900 KiB' );
$dimensions = getimagesizefromstring( $media['files']['photo']['data'] );
threadtandem_test_expect( $dimensions && max( $dimensions[0], $dimensions[1] ) <= 1600 && abs( $dimensions[0] / $dimensions[1] - 1.8 ) < 0.01, 'Upload dimensions are bounded while retaining the original aspect ratio' );
threadtandem_test_expect( hash_file( 'sha256', $upload['file'] ) === hash( 'sha256', $original ), 'Media Library original is unchanged by upload preparation' );
$again = ThreadTandem_Media::for_post( get_post( $id ) );
threadtandem_test_expect( $again['hash'] === $media['hash'] && $again['files']['photo']['data'] === $media['files']['photo']['data'], 'Repeated preparation produces the same content hash and avoids unnecessary media edits' );
threadtandem_test_expect( glob( get_temp_dir() . 'threadtandem-photo-*' ) === $temporary_before, 'Owned temporary JPEGs and placeholders are removed after preparation' );
$no_editor = static function () { return array(); };
add_filter( 'wp_image_editors', $no_editor );
$unavailable = ThreadTandem_Media::for_post( get_post( $id ) );
remove_filter( 'wp_image_editors', $no_editor );
threadtandem_test_expect( is_wp_error( $unavailable ) && $unavailable->get_error_code() === 'threadtandem_poster_size' && $unavailable->get_error_data()['state'] === 'failed', 'An unavailable image editor fails explicitly instead of uploading an oversized file or silently omitting the image' );
$threadtandem_test_next_error = array( 'headers' => array(), 'response' => array( 'code' => 413 ), 'body' => '<html>Request Entity Too Large: ' . ThreadTandem_Settings::token() . '</html>' );
wp_update_post( array( 'ID' => $id, 'post_status' => 'publish' ) ); threadtandem_test_run();
$job = threadtandem_test_job( 'post:' . $id );
threadtandem_test_expect( $job->status === 'failed' && strpos( $job->last_error, '413' ) !== false && strpos( $job->last_error, 'sendPhoto' ) !== false, 'An HTML proxy rejection is stored as a size error with safe request diagnostics' );
threadtandem_test_expect( strpos( $job->last_error, ThreadTandem_Settings::token() ) === false && ! get_post_meta( $id, '_threadtandem_publication', true ), 'The rejected send creates no false mapping and stores no token or remote body' );
threadtandem_test_expect( ThreadTandem_Queue::retry( $job->id, false ), 'A confirmed rejection can be retried without an uncertain-result acknowledgement' );
threadtandem_test_run();
$binding = get_post_meta( $id, '_threadtandem_publication', true );
$photos = threadtandem_test_methods( 'sendPhoto' ); $last = end( $photos );
threadtandem_test_expect( threadtandem_test_job( 'post:' . $id )->status === 'done' && $binding['media_type'] === 'photo' && strlen( $last['files']['photo']['data'] ) <= 900 * 1024, 'Retry with the bounded poster completes through the real queue and saves its message binding' );
$count = count( $threadtandem_test_calls );
ThreadTandem_Queue::post( $id ); threadtandem_test_run();
threadtandem_test_expect( count( $threadtandem_test_calls ) === $count, 'An unchanged retry does not duplicate or reupload the announcement' );
remove_filter( 'pre_http_request', 'threadtandem_test_http', 10 );
echo wp_json_encode( array( 'wordpress' => get_bloginfo( 'version' ), 'php' => PHP_VERSION, 'checks' => $threadtandem_test_checks ), JSON_PRETTY_PRINT ) . PHP_EOL;
WP_CLI::success( count( $threadtandem_test_checks ) . ' checks passed, including bounded photo uploads and proxy diagnostics.' );
